from collections import Counter

SALES = """Pune,450
Delhi,abc
Pune,300
Chennai,800
Delhi,650"""

def parse_sales(text):
    for line in text.splitlines():
        city, _, amount = line.partition(",")
        if not amount.isdigit():
            continue   # skip malformed rows
        yield city, int(amount)

def total_by_city(rows):
    totals = Counter()
    for city, amount in rows:
        totals[city] += amount
    return totals

def format_report(totals):
    return "\n".join(f"{city:<8}{amount:>6}" for city, amount in totals.most_common())

print(format_report(total_by_city(parse_sales(SALES))))

